bool Report::fail(Severity t)const{for(auto&f:findings)if((int)f.sev>=(int)t)return true;for(auto&d:diagnostics)if((int)d.sev>=(int)t)return true;return false;}const char* severity_name(Severity s){switch(s){case Severity::Info:return "info";case Severity::Low:return "low";case Severity::Medium:return "medium";case Severity::High:return "high";case Severity::Critical:return "critical";}return "info";}std::string trim(std::string s){auto ns=[](unsigned char c){return !std::isspace(c);};s.erase(s.begin(),std::find_if(s.begin(),s.end(),ns));s.erase(std::find_if(s.rbegin(),s.rend(),ns).base(),s.end());return s;}std::string lower(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return char(std::tolower(c));});return s;}std::vector<std::string> split(const std::string&s,char d){std::vector<std::string>v;std::string c;std::stringstream ss(s);while(std::getline(ss,c,d))v.push_back(c);if(!s.empty()&&s.back()==d)v.push_back("");return v;}std::vector<std::string> lines(const std::string&s){std::vector<std::string>v;std::string c;for(char x:s){if(x=='\n'){if(!c.empty()&&c.back()=='\r')c.pop_back();v.push_back(c);c.clear();}else c.push_back(x);}v.push_back(c);return v;}bool starts(const std::string&s,const std::string&p){return s.rfind(p,0)==0;}std::string strip_quotes(const std::string&s){return s.size()>=2&&((s.front()=='"'&&s.back()=='"')||(s.front()=='\''&&s.back()=='\''))?s.substr(1,s.size()-2):s;}std::string json_escape(const std::string&s){std::string o;for(unsigned char c:s){if(c=='"')o+="\\\"";else if(c=='\\')o+="\\\\";else if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else if(c=='\t')o+="\\t";else if(c<32)o+='?';else o+=char(c);}return o;}
std::vector<Token> shell_tokens(const std::string&l,size_t no){std::vector<Token>o;std::string c;char q=0;size_t st=1;for(size_t i=0;i<=l.size();++i){char x=i<l.size()?l[i]:' ';if(q){if(x==q)q=0;else c.push_back(x);}else if(x=='"'||x=='\''){q=x;if(c.empty())st=i+1;}else if(std::isspace((unsigned char)x)){if(!c.empty()){o.push_back({c,{"",no,st,i}});c.clear();}}else{if(c.empty())st=i+1;c.push_back(x);}}return o;}
Result<void> ByteReader::skip(size_t m){if(!can(m))return Status::error(Code::Range,"short skip",p);p+=m;return{};}Result<uint8_t> ByteReader::u8(){if(!can(1))return Status::error(Code::Range,"short read",p);return d[p++];}Result<uint16_t> ByteReader::u16(){if(!can(2))return Status::error(Code::Range,"short read",p);uint16_t v=le?uint16_t(d[p])|(uint16_t(d[p+1])<<8):(uint16_t(d[p])<<8)|d[p+1];p+=2;return v;}Result<uint32_t> ByteReader::u32(){if(!can(4))return Status::error(Code::Range,"short read",p);uint32_t v=le?uint32_t(d[p])|(uint32_t(d[p+1])<<8)|(uint32_t(d[p+2])<<16)|(uint32_t(d[p+3])<<24):(uint32_t(d[p])<<24)|(uint32_t(d[p+1])<<16)|(uint32_t(d[p+2])<<8)|d[p+3];p+=4;return v;}Result<std::vector<uint8_t>> ByteReader::bytes(size_t m){if(!can(m))return Status::error(Code::Range,"short read",p);std::vector<uint8_t>v(d+p,d+p+m);p+=m;return v;}Result<uint32_t> BitReader::bits(int c){if(c<0||c>24)return Status::error(Code::Invalid,"bad bit count");uint32_t v=0;for(int i=0;i<c;i++){if(!left){auto b=r.u8();if(!b)return b.st;cur=b.value();left=8;}v=(v<<1)|((cur>>(left-1))&1);--left;}return v;}
std::string IPv4::text()const{std::ostringstream o;o<<((v>>24)&255)<<'.'<<((v>>16)&255)<<'.'<<((v>>8)&255)<<'.'<<(v&255);return o.str();}bool CIDR::contains(IPv4 ip)const{uint32_t m=prefix?0xffffffffu<<(32-prefix):0;return (ip.v&m)==(net.v&m);}std::string CIDR::text()const{return net.text()+"/"+std::to_string(prefix);}std::string PortRange::text()const{return a==b?std::to_string(a):std::to_string(a)+":"+std::to_string(b);}Result<IPv4> parse_ipv4(const std::string&s){auto p=split(trim(s),'.');if(p.size()!=4)return Status::error(Code::Malformed,"bad IPv4");uint32_t v=0;for(auto&x:p){if(x.empty()||x.size()>3)return Status::error(Code::Malformed,"bad octet");int n=0;for(char c:x){if(!std::isdigit((unsigned char)c))return Status::error(Code::Malformed,"bad octet");n=n*10+c-'0';}if(n>255)return Status::error(Code::Range,"octet range");v=(v<<8)|uint32_t(n);}return IPv4{v};}Result<CIDR> parse_cidr(const std::string&s){auto t=trim(s);auto p=t.find('/');auto ip=parse_ipv4(p==std::string::npos?t:t.substr(0,p));if(!ip)return ip.st;int pref=32;if(p!=std::string::npos){auto x=t.substr(p+1);if(x.empty())return Status::error(Code::Malformed,"missing prefix");pref=0;for(char c:x){if(!std::isdigit((unsigned char)c))return Status::error(Code::Malformed,"bad prefix");pref=pref*10+c-'0';}if(pref<0||pref>32)return Status::error(Code::Range,"prefix range");}uint32_t m=pref?0xffffffffu<<(32-pref):0;return CIDR{IPv4{ip.value().v&m},uint8_t(pref)};}Result<PortRange> parse_port_range(const std::string&s){auto t=lower(trim(s));if(t=="any"||t=="*")return PortRange{};char d=t.find(':')!=std::string::npos?':':'-';auto ps=split(t,d);auto pp=[](const std::string&x)->Result<uint16_t>{if(x.empty())return Status::error(Code::Malformed,"empty port");int n=0;for(char c:x){if(!std::isdigit((unsigned char)c))return Status::error(Code::Malformed,"bad port");n=n*10+c-'0';}if(n>65535)return Status::error(Code::Range,"port range");return uint16_t(n);};if(ps.size()==1){auto p=pp(ps[0]);if(!p)return p.st;return PortRange{p.value(),p.value()};}if(ps.size()==2){auto a=pp(ps[0]),b=pp(ps[1]);if(!a)return a.st;if(!b)return b.st;if(a.value()>b.value())return Status::error(Code::Invalid,"reversed ports");return PortRange{a.value(),b.value()};}return Status::error(Code::Malformed,"bad ports");}
HashKind detect_hash(const std::string&s){auto t=trim(s);if(!std::all_of(t.begin(),t.end(),[](unsigned char c){return std::isxdigit(c);}))return HashKind::Unknown;if(t.size()==32)return HashKind::MD5;if(t.size()==40)return HashKind::SHA1;if(t.size()==64)return HashKind::SHA256;return HashKind::Unknown;}bool domain_like(const std::string&s){auto t=lower(trim(s));if(t.size()>253||t.find('.')==std::string::npos||t.front()=='.'||t.back()=='.')return false;for(char c:t)if(!(std::isalnum((unsigned char)c)||c=='-'||c=='.'))return false;return true;}bool url_like(const std::string&s){auto t=lower(trim(s));return starts(t,"http://")||starts(t,"https://");}std::string norm_domain(const std::string&s){auto t=lower(trim(strip_quotes(s)));while(!t.empty()&&t.back()=='.')t.pop_back();return t;}std::string norm_url(const std::string&s){auto t=strip_quotes(trim(s));auto l=lower(t);auto p=l.find("://");std::string scheme=p==std::string::npos?"http":l.substr(0,p),rest=p==std::string::npos?t:t.substr(p+3);auto slash=rest.find('/');return scheme+"://"+norm_domain(rest.substr(0,slash))+(slash==std::string::npos?"/":rest.substr(slash));}std::vector<std::string> words(const std::string&s){std::vector<std::string>o;std::string c;for(char x:s){if(std::isalnum((unsigned char)x)||x=='.'||x=='-'||x=='_'||x==':'||x=='/')c.push_back(x);else if(!c.empty()){o.push_back(c);c.clear();}}if(!c.empty())o.push_back(c);return o;}Result<std::string> read_text(const std::string&p){std::ifstream f(p,std::ios::binary);if(!f)return Status::error(Code::Io,"open failed");return std::string((std::istreambuf_iterator<char>(f)),{});}std::vector<uint8_t> read_bytes(const std::string&p){std::ifstream f(p,std::ios::binary);return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),{});}std::string report_text(const Report&r){std::ostringstream o;if(!r.subject.empty())o<<r.subject<<"\n";for(auto&d:r.diagnostics)o<<severity_name(d.sev)<<" diagnostic "<<d.code<<" line "<<d.loc.line<<": "<<d.msg<<"\n";for(auto&f:r.findings)o<<severity_name(f.sev)<<" "<<f.cat<<": "<<f.title<<" - "<<f.detail<<"\n";if(r.diagnostics.empty()&&r.findings.empty())o<<"No issues detected\n";return o.str();}std::string report_json(const Report&r){std::ostringstream o;o<<"{\"subject\":\""<<json_escape(r.subject)<<"\",\"findings\":[";bool first=true;for(auto&f:r.findings){if(!first)o<<",";first=false;o<<"{\"severity\":\""<<severity_name(f.sev)<<"\",\"category\":\""<<json_escape(f.cat)<<"\",\"title\":\""<<json_escape(f.title)<<"\",\"detail\":\""<<json_escape(f.detail)<<"\"}";}o<<"],\"diagnostics\":[";first=true;for(auto&d:r.diagnostics){if(!first)o<<",";first=false;o<<"{\"severity\":\""<<severity_name(d.sev)<<"\",\"code\":\""<<json_escape(d.code)<<"\",\"message\":\""<<json_escape(d.msg)<<"\"}";}o<<"]}";return o.str();}
